readingTasks['ja:7']=[
 choose('apply','窓口が満足度調査を追加し、利用中の人の評価は上がりました。しかし、利用をやめた人は調査していません。','この結果から言えることの限界は何ですか。',['満足度も改善したので、相談者全体の問題は解決した。','調査項目が増えたので、成果の定義を問い直す必要はない。','利用をやめた人の経験が欠けており、見えなくなった不満は評価できない。','利用中の人の評価は、調査対象が誰であっても無意味である。'],2,'筆者は測定を否定せず、誰の経験が測定から外れたかを問うています。'),
 choose('evidence','議事録を「沈黙した人は全員反対だった」と書き直す案が出ました。','その案も筆者の立場と違うことを示す一文を探しましょう。',['先日の会議は、実に円滑でした。','もっとも、沈黙した人は皆、本当は反対だった、と決めつけるのも乱暴です。','議事録には、全員の了承を得た、とあります。','私はあの場で賛成した記憶がないのですが、反対しなかったことまで否定するつもりはありません。'],1,'賛成にも反対にも、沈黙の意味を一方的に確定しない立場です。'),
 choose('apply','改修案に、外観保存と家賃支援が加わりました。ただし、支援期間後に元の店主が営業を続けられるかは調べていません。','筆者の問題意識に沿って、さらに何を検討しますか。',['看板の再現精度だけを高め、保存の成否を判断する。','支援が一度でもあれば、暮らしの連続性は保証されたとする。','建物を改修しなければ、生活上の問題もすべて解消するとする。','安全性と、店主が関係を保ちながら営業を続けられる条件を併せて検討する。'],3,'筆者は改修自体に反対せず、誰のどのような連続性を守るかを問うています。')
];
readingTasks['ko:7-1']=[
 choose('evidence','성과를 수치로 측정하면 공정한 평가가 가능하다는 의견을 검토해요.','측정하기 쉬운 성과와 필요한 기여가 다를 수 있음을 보여 주는 문장을 고르세요.',['새 평가제도는 숫자로 성과를 보여 준다는 점에서 공정해 보인다.','그렇다고 숫자를 모두 버리자는 뜻은 아니다.','측정하기 쉬운 일을 잘하는 사람과 조직에 꼭 필요한 일을 하는 사람이 늘 같은 것은 아니다.','지표가 설명하지 못하는 부분까지 지표의 탓이 아닌 개인의 무능으로 돌리는 순간, 평가가 오히려 조직을 망칠 수 있다는 것이다.'],2,'측정하기 쉬운 성과와 필요한 기여가 다를 수 있다는 점이 이 전제에 대한 반론이에요.'),
 choose('apply','설명회 자료를 미리 나눠 주기로 했어요. 하지만 주민의 의견을 들어도 공사 계획은 바꾸지 않겠다고 해요.','이 변경만으로 참석자의 비판에 답했다고 볼 수 있나요?',['그렇다. 자료를 일찍 보내면 의견 반영 여부는 중요하지 않다.','아니다. 의견이 계획에 반영될 여지가 없다면 형식적인 소통이라는 문제는 남는다.','그렇다. 설명회를 열었다는 사실만으로 주민의 동의가 성립한다.','아니다. 참석자는 공사 자체를 어떤 조건에서도 반대하기 때문이다.'],1,'안내가 늦었다는 점뿐 아니라 의견을 반영할 여지가 없다는 점도 비판하고 있어요.'),
 choose('apply','지원을 받지 않은 비슷한 지역에서도 같은 시기에 매출이 비슷하게 늘었다는 사실이 확인됐어요.','이 정보를 고려할 때 가장 신중한 결론은 무엇인가요?',['지원은 어떤 경우에도 효과가 없다고 확정할 수 있다.','관광객 증가는 지원의 효과와 무관하므로 고려할 필요가 없다.','매출이 늘었으므로 지원만의 성과라고 할 수 있다.','공통 요인의 영향을 더 살펴야 하며, 지원만의 효과라고 단정하기 어렵다.'],3,'비교 결과는 인과관계를 따져 볼 근거예요. 지원만이 원인이라거나 효과가 전혀 없다고 단정할 수는 없어요.')
];
export function caseExercises(s,kind,source){
 if(kind==='sentence'&&sentenceId(s)>0)return extraSentenceCases[sentenceId(s)].tasks;
 if(kind==='korean'&&extraKoreanCases[s.korean.active])return extraKoreanCases[s.korean.active].tasks;
 if(kind==='sentence'||kind==='dialogue')return cases[kind];
 if(kind==='korean'&&cases[`ko:${s.korean.active}`])return cases[`ko:${s.korean.active}`].map((task,i)=>s.korean.active==='3-1'?{...task,...exchangeTaskFeedback[i]}:task);
 const key=kind==='korean'?`ko:${s.korean.active}`:`ja:${s.onboardingLevel}`,tasks=readingTasks[key];
 return tasks?.map((task,i)=>({...task,passage:kind==='korean'?source.koreanContent[s.korean.active][i].text:source.readingCourses[s.onboardingLevel].passages[i].paragraphs.join('\n')}));
}
